// Late raw edit sessions are not candidate-list actions, and need independent guards.
#define WANGSHU_SELECTION_FIXTURES_ONLY
#include "selection_scope_test.cpp"
static int good=0,bad=0;
static void scenario(const char* name,const std::function<void()>& run){try{run();++good;std::cout<<"PASS "<<name<<std::endl;}catch(const std::exception& error){++bad;std::cout<<"FAIL "<<name<<" :: "<<error.what()<<std::endl;}}
int main(){
    scenario("unchanged async raw commit remains usable",[]{SelectionFixture f;f.context->deferred=true;requireSelection(TextServiceTestAccess::click(f.service,f.context,"raw-completion"),"Queue rejected");auto results=f.context->flush();requireSelection(results.size()==1&&SUCCEEDED(results[0])&&f.context->document.text==L"beforeraw-completionafter"&&f.context->document.textWrites==1,"Current async raw commit failed");});
    scenario("host text change after async raw queue is preserved",[]{SelectionFixture f;auto& d=f.context->document;f.context->deferred=true;TextServiceTestAccess::click(f.service,f.context,"raw-completion");d.text.replace(6,5,L"fresh");auto before=d.text;auto results=f.context->flush();requireSelection(results.size()==1&&FAILED(results[0])&&d.text==before&&d.textWrites==0&&TextServiceTestAccess::pendingText(f.service)=="nihao","Queued raw commit overwrote changed host composition");});
    scenario("host caret change after async raw queue is preserved",[]{SelectionFixture f;auto& d=f.context->document;f.context->deferred=true;TextServiceTestAccess::click(f.service,f.context,"raw-completion");d.start=d.end=2;auto before=d.text;auto results=f.context->flush();requireSelection(results.size()==1&&FAILED(results[0])&&d.text==before&&d.start==2&&d.end==2&&d.textWrites==0&&d.selectionWrites==0,"Queued raw commit moved current host caret");});
    scenario("focus cleanup refuses independently changed host text",[]{SelectionFixture f;auto& d=f.context->document;f.context->deferred=true;f.service->OnSetFocus(static_cast<ITfDocumentMgr*>(nullptr),static_cast<ITfDocumentMgr*>(nullptr));d.text.replace(6,5,L"fresh");auto before=d.text;auto results=f.context->flush();requireSelection(results.size()==1&&FAILED(results[0])&&d.text==before&&d.textWrites==0,"Focus cleanup restored stale composition over host text");});
    scenario("queued focus cleanup cannot finish a newer typing revision",[]{SelectionFixture f;auto& d=f.context->document;f.context->deferred=true;f.service->OnSetFocus(static_cast<ITfDocumentMgr*>(nullptr),static_cast<ITfDocumentMgr*>(nullptr));BOOL eaten=FALSE;f.service->OnKeyDown(f.context,'K',0,&eaten);requireSelection(eaten&&TextServiceTestAccess::pendingText(f.service)=="k","New input fixture did not reach production editor");auto before=d.text;auto writes=d.textWrites;auto selections=d.selectionWrites;auto results=f.context->flush();requireSelection(results.size()==1&&FAILED(results[0])&&d.text==before&&d.textWrites==writes&&d.selectionWrites==selections&&TextServiceTestAccess::pendingText(f.service)=="k","Old unnotified session rewrote or terminated newer composition");});
    scenario("ordinary focus cleanup still finishes exact old composition",[]{SelectionFixture f;auto& d=f.context->document;f.context->deferred=true;f.service->OnSetFocus(static_cast<ITfDocumentMgr*>(nullptr),static_cast<ITfDocumentMgr*>(nullptr));auto results=f.context->flush();requireSelection(results.size()==1&&SUCCEEDED(results[0])&&d.text==L"beforenihaoafter"&&d.textWrites==1,"Exact focus cleanup failed");});
    scenario("separate async fixtures release COM ownership",[]{requireSelection(objectCount==0,"Leaked COM fixture ownership");});
    std::cout<<"RESULT passed="<<good<<" failed="<<bad<<" total="<<(good+bad)<<"; production PE with controlled deferred TSF host; real Windows NOT_RUN"<<std::endl;return bad?1:0;
}
